css:
[data-cat-menu]{position:relative;display:inline-block}
.cat-menu{position:absolute;top:calc(100% + 6px);left:0;min-width:200px;padding:5px;border-radius:var(--cat-size-radius-md);background:var(--cat-color-surface-menu);backdrop-filter:blur(var(--cat-blur-float)) saturate(var(--cat-blur-saturate-float));-webkit-backdrop-filter:blur(var(--cat-blur-float)) saturate(var(--cat-blur-saturate-float));border:1px solid var(--cat-color-stroke-menu);box-shadow:var(--cat-elevation-menu);z-index:var(--cat-depth-z-dropdown);opacity:0;transform:translateY(-4px);pointer-events:none;transition:opacity var(--cat-motion-fast) var(--cat-motion-ease-out),transform var(--cat-motion-fast) var(--cat-motion-ease-out)}
.cat-menu.open,.open>.cat-menu{opacity:1;transform:none;pointer-events:auto}
.cat-menu-item{display:flex;align-items:center;justify-content:space-between;gap:18px;width:calc(100% - 4px);height:27px;margin:0 2px;padding:0 8px;border-radius:var(--cat-size-radius-menu-item);font:400 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-hi);text-align:left;background:none;border:none;cursor:pointer}
.cat-menu-item:hover{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff}
.cat-menu-item:hover .menu-kbd{color:rgba(255,255,255,.72)}
.cat-menu-item.checked .mi-check{visibility:visible}
.mi-check{visibility:hidden;font-size:11px}
.cat-menu-sep{height:1px;margin:5px 8px;background:var(--cat-color-stroke-dark)}
.menu-kbd{font-size:var(--cat-font-size-sm);color:var(--cat-color-ink-low);letter-spacing:.02em}
.cat-menu.up{top:auto;bottom:calc(100% + 6px);transform:translateY(4px)}
.cat-menu.up.open{transform:translateY(0)}
